  function oilTex() { return HSX.canvasOf(300, 600, function (q, w, h) { var S = 100, r = HSX.rnd(17), i; q.clearRect(0, 0, w, h); for (i = 0; i < 26; i++) { var x = (0.7 + r() * 1.6) * S, y = (1.4 + r() * 4.0) * S, rr = (0.05 + r() * 0.3) * S, g = q.createRadialGradient(x, y, 0, x, y, rr); g.addColorStop(0, 'rgba(28,26,24,.55)'); g.addColorStop(1, 'rgba(28,26,24,0)'); q.fillStyle = g; q.fillRect(x - rr, y - rr, rr * 2, rr * 2); }
    q.strokeStyle = 'rgba(40,38,34,.35)'; q.lineWidth = 22; [0.95, 2.05].forEach(function (x) { q.beginPath(); q.moveTo(x * S, 6 * S); q.lineTo(x * S + 8, 0.6 * S); q.stroke(); }); /* tyre tracks */
    for (i = 0; i < 900; i++) { q.fillStyle = 'rgba(200,196,186,' + (0.05 + r() * 0.12).toFixed(2) + ')'; q.fillRect(r() * w, r() * h, 2, 2); } }); }
