    scene.add(new THREE.HemisphereLight(0xeef2f6, 0x5b574f, 0.36)); var sun = new THREE.SpotLight(0xfff1dc, 1.15, 40, 0.42, 0.4, 1); sun.position.set(5, 9, 16); sun.target.position.set(1.5, 0, 3); sun.castShadow = true; sun.shadow.mapSize.set(SMALL3D ? 1024 : 2048, SMALL3D ? 1024 : 2048); sun.shadow.bias = -0.0004; sun.shadow.camera.near = 5; sun.shadow.camera.far = 35; scene.add(sun, sun.target); /* the sun as a far spot: the crew's materials take spot shadows */
    HSX.lamp(kit, scene, [2.6, 1.7, 0.6], [1.2, 0, 3], { i: 1.0, dist: 8 }); var tube = new THREE.Mesh(kit.keep(new THREE.BoxGeometry(0.1, 0.05, 1.25)), kit.std({ color: 0xffffff, emissive: 0xf6f9ff, emissiveIntensity: 1.2 })); tube.position.set(1.5, GH - 0.03, 2.4); scene.add(tube); var pl = new THREE.PointLight(0xf4f8ff, 0.5, 8, 1.5); pl.position.set(1.5, GH - 0.2, 2.4); scene.add(pl);
